using System;using System.IO;using System.Linq;using System.Runtime.InteropServices;
namespace DoomSNESed {
    public static class MusicSteadyTests {
        [DllImport("DoomSNESAudio.dll",CallingConvention=CallingConvention.Cdecl)]static extern int DoomAudioScan(byte[] driver,byte[] ram,int song,int origin,int frames,[Out]int[] records,int capacity);
        static void Check(bool value,string message){Bin.Require(value,"Steady music: "+message);}
        public static void Run(string path,string output){var rom=new Rom(path,Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"editor-data"));var score=new ImportedMusic{Name="120 BPM six-voice sixteenths",Report="",Seconds=10,QuarterSeconds=.5};
            var settings=new MusicSettings();for(int c=0;c<6;c++){settings.Assignments.Add(new MusicAssignment{Channel=c,Patch=c%2==0?44:45});for(int i=0;i<64;i++)score.Notes.Add(new MusicNote{Start=i*.125,End=i*.125+.1,Key=48+i%12,Velocity=100,Channel=c});}
            var clock=MusicClock.Choose(score,10);Check(Math.Abs(clock.Rate-48)<.0001&&clock.Tempo==246,"regular sixteenths align to six score ticks");Check(Math.Abs(clock.NativeRate/clock.Rate-1)<.0015,"native tempo rounding remains below 0.15 percent");
            var song=MusicImport.Convert(score,"E1M1",6,0,false,settings);var oldGrid=ProjectJson.Create().Deserialize<MusicSettings>(ProjectJson.Create().Serialize(settings));oldGrid.Grid=10;Check(song.Sequence.SequenceEqual(MusicImport.Convert(score,"E1M1",6,0,false,oldGrid).Sequence),"old saved coarse grids no longer distort beats");
            int[] records=new int[200000*8];int n=DoomAudioScan(NativeMusicGate.Driver(rom.Bytes),MusicBank.PreviewRam(rom.Bytes,song),settings.Song,settings.Origin,320000,records,200000);var attacks=Enumerable.Range(0,n).Where(i=>records[i*8+1]==0x18b0&&records[i*8+3]!=1).GroupBy(i=>records[i*8+4]).ToArray();Check(attacks.Length==6,"all six native tracks play");foreach(var voice in attacks){double[] times=voice.Select(i=>records[i*8]/1024000.0).ToArray();Check(times.Length==64,"steady beat retains every onset");Check(times.Select((t,i)=>Math.Abs(t-times[0]-i*.125)).Max()<.045,"beat phase stays within retail scheduling limits");}
            var percussion=new ImportedMusic{Name="Native toms and timpani",Report="",Seconds=4};int[] keys={41,43,45,47,48,50};for(int i=0;i<keys.Length;i++)percussion.Notes.Add(new MusicNote{Channel=9,Key=keys[i],Velocity=100,Start=i*.25,End=i*.25+.15});percussion.Notes.Add(new MusicNote{Program=47,Key=40,Velocity=100,Start=0,End=1});percussion.Notes.Add(new MusicNote{Channel=1,Program=117,Key=48,Velocity=100,Start=2,End=3});
            var mapping=MusicBank.Automatic(rom.Bytes,percussion);Check(mapping.Assignments.Where(a=>a.Channel==9).All(a=>a.Patch==43),"all six GM tom notes use the real tom sample");Check(mapping.Assignments.Single(a=>a.Program==47&&a.Channel!=9).Patch==67,"GM timpani selects the real timpani sample");Check(mapping.Assignments.Single(a=>a.Program==117).Patch==43,"GM melodic tom selects the real tom sample");
            for(int i=0;i<keys.Length;i++)Check(NativeVoicing.Pitch(percussion.Notes[i],43)==keys[i]+24,"tom tuning follows the retail octave calibration");Check(NativeVoicing.Pitch(percussion.Notes[6],67)==40,"timpani retains its melodic pitch");
            var converted=MusicImport.Convert(percussion,"E1M1",6,0,false,mapping);int rate;var pcm=NativeAudio.Render(rom.Bytes,MusicBank.PreviewRam(rom.Bytes,converted),0,mapping.Song,4,out rate);Check(pcm.Any(v=>v!=0),"native drum and timpani conversion is audible");
            rom.Project.RetailAssets=true;rom.Project.CompactAssets=true;rom.Project.Audio.Music.Add(converted);byte[] image=rom.Compile();Check(AudioRom.Module(image,MusicTargets.Read(image,"E1M1")>>8).SequenceEqual(MusicBank.PreviewRam(rom.Bytes,converted)),"mixed percussion ROM upload matches preview");
            File.WriteAllText(Path.Combine(output,"music-steady-016-results.txt"),"PASS six-voice beat alignment and bounded native phase; legacy coarse-grid migration; GM drum toms, melodic tom and timpani mappings, tuning, native audio and ROM/preview parity.\r\n");
        }
    }
}
